package got.world.genlayer; public class GOTGenLayerBiomeVariantsLake extends GOTGenLayer {private final int zoomScale;private int lakeFlags;public GOTGenLayerBiomeVariantsLake(long s,GOTGenLayer p,int z){super(s);gotParent=p;zoomScale=z;}public static boolean getFlag(int value,int flag){return (value&(1<<flag))!=0;}private static int setFlag(int value,int flag){return value|(1<<flag);}public GOTGenLayerBiomeVariantsLake setLakeFlags(int... flags){for(int f:flags)lakeFlags=setFlag(lakeFlags,f);return this;}public int[] getInts(int x,int z,int w,int h){int[] o=gotParent==null?new int[w*h]:gotParent.getInts(x,z,w,h);for(int dz=0;dz<h;dz++)for(int dx=0;dx<w;dx++){initChunkSeed(x+dx,z+dz);if(nextInt(Math.max(8,80-(zoomScale*10)))==0)o[dx+dz*w]|=lakeFlags;}return o;}}